"""Pure-Python logic shared by the Fusion add-in and the service.

Standard library only: this package is imported inside Fusion's bundled Python.
Fusion 2705.1.15 bundles Python 3.14 (api_probe, 2026-10-01); CI tests this package on 3.14.
"""

# job.json and result.json carry this. The Fusion worker refuses a job built by a
# different version, so a long-lived Fusion process can't run stale code.
CORE_VERSION = "0.29.0"  # 0.29.0: parts drawn off square laid square in every Arrange (NestSpec.square_parts, pipeline._square_probe); 0.28.0: offcuts on the rack turned round freely (OffcutSpec.on_bed), the smallest offcut that fits kept, straight rows laid along a straight edge (Arrange: setRotationUsingEdge); 0.27.0: straight rows tried after Fusion nests a sheet (rows.py, NestSpec.straight_max); 0.26.0: outlines last for hole fits (FitSpec.outline_last, an OUTLINES program after the laps); 0.25.0: the clamp strips as fixtures in the Fusion setups (FixtureSpec.clamps_in_fusion); 0.24.1: an area nothing fits places nothing (Fusion raises ARRANGE_ERROR_NO_ROOM, r084); 0.24.0: spares (PartSpec.spare) nest only in the room robot parts leave; 0.23.0: one nest order (Arrange ignored order) and Arrange priorities by size, every sheet squeezed; 0.22.0: rooms on an offcut from where the program really cuts (cutmap.py), not the parts' boxes; 0.21.0: the stop between parts is a bare G4 that waits for ENTER (WinCNC has no M0); 0.20.6: rooms on an offcut are every empty rectangle among the parts (offcuts.free_rooms), not just the room to their right; 0.20.5: small curvy cutouts cut free beside wide tabs (TabSpec.free_max_in); 0.19.0: small features split off into a small-tool program (ToolingSpec.split, kind "small"); 0.18.0: scribed bend lines (PartSpec.scribe, ScribeSpec, [scribe] op, SCRIBE program); 0.17.0: bent parts (PartSpec.bends, the flat pattern cut); 0.16.0: fit series (PartSpec.fit, FIT lap programs); 0.15.0: [bearing] op, holes.bearing_stock_in; 0.14.0: faced parts (a FACE program per sheet); 0.13.0: pockets ([pocket], [pocketfinish]); 0.12.1: labels in the middle of thin parts; 0.12.0: parts placed by hand; 0.11.0: tab width/height
